  "description": "Flags a dataset or record when its quality score falls below an acceptable threshold, suggesting the data may be unreliable.",
  "definition": "A state triggered when a data quality assessment score is below a predefined minimum standard, for instance, a score of less than 50 out of 100."
}

{
  "id": 29,
  "knowledge": "Critical Alert",
  "description": "An urgent notification indicating a severe issue that requires immediate maintenance and potential component replacement.",
  "definition": "A state is defined as a Critical Alert when an asset has both a High Maintenance Priority and a High Replacement Priority."
}

{
  "id": 32,
  "knowledge": "Underperforming Asset",
  "description": "An asset whose energy conversion efficiency is significantly below its expected benchmark.",
  "definition": "An asset is classified as underperforming if its Performance Ratio (PR) falls below a minimum acceptable threshold, such as 0.75."
}

{
  "id": 38,
  "knowledge": "Neglected Asset",
  "description": "An asset that is in a critical state but is not receiving the required attention, indicated by data quality issues and overdue maintenance.",
  "definition": "An asset is defined as neglected if it has an active Critical Alert, is subject to Overdue Critical Maintenance, and also has a Data Quality Concern."
}

{
  "id": 33,
  "knowledge": "Chronic Downtime Asset",
  "description": "An asset that suffers from frequent failures and low operational uptime.",
  "definition": "An asset is classified as having chronic downtime if its System Availability is below a critical threshold, for example, 95%."
}

{
  "id": 35,
  "knowledge": "Critical Mechanical Health",
  "description": "Indicates that an asset is suffering from severe and concurrent mechanical failures.",
  "definition": "A state of critical mechanical health is reached when there is an active Structural Integrity Warning and a simultaneous Tracker Malfunction."
}

{
  "id": 8,
  "knowledge": "System Availability",
  "description": "Calculates the proportion of time a system is operational and available to perform its required function.",
  "definition": "The probability that a system is operational, calculated as: $A = 1 - \\text{System Unavailability}$. A value of 99% implies the system is non-operational for 1% of the time."
}

{
