CREATE TABLE compliance_issues (
    id SERIAL PRIMARY KEY,
    plant_id TEXT NOT NULL,
    description TEXT NOT NULL,
    issue_date DATE NOT NULL
);

INSERT INTO compliance_issues (plant_id, description, issue_date)
SELECT sitekey, 'Plant is not compliant', goliveon
FROM plants
WHERE complyflag = 'Non-Compliant';
